control 'safbox-accounts-2' do
  impact 1.0
  title 'cloud-init creates no default user unless a datasource asks for one'
  desc 'The system configuration sets users to an empty list, so a boot without user data (the build ' \
       'VM, or a clone deployed without a user) creates no default account. User data that names a ' \
       'user, as a deployment does, still gets one built from the distribution default_user definition.'

  describe 'merged cloud-init system configuration' do
    subject { cloud_cfg_cmd }
    its('exit_status') { should eq 0 }
  end

  describe 'cloud-init system users' do
    subject { cloud_cfg['users'] }
    it { should eq [] }
  end

  describe 'cloud-init default_user definition (used when user data names a user)' do
    subject { cloud_cfg['default_user'] }
    it { should_not be_nil }
  end
end

control 'safbox-build-info-1' do
  impact 1.0
  title 'The build record exists and names the distribution and microarchitecture level'
  desc 'ADR-0001 Risks: the image records which distribution and microarchitecture level it was built ' \
       'from so a lab artifact is never mistaken for a release artifact. Written by the seal step ' \
       'outside the root-only /etc/safbox, since it is not a secret and safbox status reads it, ' \
       'which also records the exact builds of packages the install layer installs unpinned.'
  only_if('build record is written by the seal step, which has not run yet') { input('build_info_expected') }

  describe file(build_info_path) do
    it { should exist }
    its('owner') { should eq 'root' }
    its('mode') { should cmp '0644' }
    its('content') { should match(/^SAFBOX_BUILD_DATE=\d{4}-\d{2}-\d{2}T/) }
    its('content') { should match(/^SAFBOX_GIT_COMMIT=\S+$/) }
    its('content') { should match(/^SAFBOX_DISTRIBUTION=\S+$/) }
    its('content') { should match(/^SAFBOX_DISTRIBUTION_VERSION=\S+$/) }
    its('content') { should match(/^SAFBOX_PACKAGE_ARCH=\S+$/) }
    its('content') { should match(/^SAFBOX_MICROARCH_LEVEL=(x86-64-v[234]|n\/a)$/) }
    its('content') { should match(/^SAFBOX_FIPS_ENABLED=1$/) }
    its('content') { should match(/^SAFBOX_SEAL_MODE=#{Regexp.escape(input('seal_mode_expected'))}$/) }
    its('content') { should match(/^SAFBOX_UNPINNED_PACKAGES=.*\bcloud-init-\d/) }
    its('content') { should match(/^SAFBOX_UNPINNED_PACKAGES=.*\bqemu-guest-agent-\d/) }
  end

  describe command('runuser -u nobody -- /usr/local/bin/safbox status') do
    its('stdout') { should match(/^Microarchitecture level:\s+x86-64-v[234]$/) }
    its('stdout') { should match(/^Build MICROARCH_LEVEL:\s+\S/) }
  end

  # Surface the recorded values in the test description so the results carry them.
  if file(build_info_path).exist?
    build_info = parse_config_file(build_info_path)
    describe "built from #{build_info['SAFBOX_DISTRIBUTION']} #{build_info['SAFBOX_DISTRIBUTION_VERSION']} " \
             "#{build_info['SAFBOX_PACKAGE_ARCH']} at #{build_info['SAFBOX_MICROARCH_LEVEL']}" do
      subject { build_info['SAFBOX_DISTRIBUTION'] }
      it { should_not be_nil }
    end
  end
end

control 'safbox-cli-1' do
  impact 1.0
  title 'The safbox command and its subcommand registry are installed'
  desc 'ADR-0001 §Shared Abstractions: the safbox command of the base role, with subcommand registration.'

  describe file('/usr/local/bin/safbox') do
    it { should exist }
    it { should be_executable }
    its('owner') { should eq 'root' }
  end

  describe directory('/usr/local/lib/safbox/commands') do
    it { should exist }
    its('owner') { should eq 'root' }
  end

  describe file('/usr/local/lib/safbox/commands/status') do
    it { should exist }
    it { should be_executable }
  end

  describe command('/usr/local/bin/safbox help') do
    its('exit_status') { should eq 0 }
    its('stdout') { should match(/^\s+status\s/) }
  end

  describe command('/usr/local/bin/safbox status') do
    its('exit_status') { should eq 0 }
    its('stdout') { should match(/^Distribution:/) }
    its('stdout') { should match(/^Microarchitecture level:\s+\S/) }
    its('stdout') { should match(/^FIPS mode:\s+enabled/) }
    its('stdout') { should match(/^First boot:/) }
    # One row per tool group, with the version or 'not installed'; the
    # versions themselves are checked by the safbox-tools-<n> controls.
    its('stdout') { should match(/^CINC Auditor:\s+\S/) }
    its('stdout') { should match(/^SAF CLI:\s+\S/) }
    its('stdout') { should match(/^Ansible core:\s+\S/) }
    its('stdout') { should match(/^Packer:\s+\S/) }
  end
end

control 'safbox-cli-2' do
  impact 1.0
  title 'safbox services reports the health of the proxy, Heimdall and Vulcan and of their units'
  desc "ADR-0001 Phase 8: safbox services reports unit health for each service the image ships. Each service role registers its service in #{services_registry} (a label and the units that make it up); the command reads systemd's view of each unit, so any user may run it, and sums each service up as running, starting, stopping, waiting (a unit's condition failed: first boot has not written its secrets or certificate), stopped, failed or not installed. It exits 0 only when every registered service runs, and 3 otherwise. On a deployed clone every service runs; on the build VM none has started."

  describe file('/usr/local/lib/safbox/commands/services') do
    it { should exist }
    it { should be_executable }
    its('owner') { should eq 'root' }
  end

  describe command('/usr/local/bin/safbox help') do
    its('stdout') { should match(/^\s+services\s+\S/) }
  end

  describe command("sh -c 'ls -1 #{services_registry}'") do
    its('stdout.split') { should eq expected_services.map { |s| registered_services[s][:file] }.sort }
  end

  want = deployed ? 'running' : 'stopped'
  want_active = deployed ? 'active' : 'inactive'
  tsv = command('runuser -u nobody -- /usr/local/bin/safbox services --tsv')
  describe tsv do
    its('exit_status') { should eq(deployed ? 0 : 3) }
  end
  describe 'Services safbox services --tsv reports, as name, label and health' do
    subject { tsv.stdout.lines.map { |line| line.chomp.split("\t") }.sort }
    it { should eq expected_services.map { |s| [s, registered_services[s][:label], want] }.sort }
  end

  human = command('runuser -u nobody -- /usr/local/bin/safbox services')
  expected_services.each do |service|
    describe "safbox services for #{service}" do
      subject { human.stdout }
      it { should match(/^#{Regexp.escape(registered_services[service][:label])}\s+#{want}$/) }
      registered_services[service][:units].each do |unit|
        it { should match(/^\s+#{Regexp.escape(unit)}\s+#{want_active} \(/) }
      end
    end
  end
end

control 'safbox-fips-1' do
  impact 1.0
  title 'FIPS mode is enabled and was set at install'
  desc 'ADR-0001: FIPS mode is on from installation and is not configurable afterward. The kernel must report fips_enabled=1 and fips=1 must be on the command line.'
  only_if('FIPS is not required for this image') { input('fips_required') }

  describe file('/proc/sys/crypto/fips_enabled') do
    it { should exist }
    its('content.strip') { should cmp '1' }
  end

  describe file('/proc/cmdline') do
    its('content') { should match(/(^|\s)fips=1(\s|$)/) }
  end
end

control 'safbox-fips-2' do
  impact 1.0
  title 'The system-wide crypto policy is FIPS'
  desc 'A FIPS install sets the crypto-policies level to FIPS; any other policy lets userland negotiate algorithms outside the validated module.'
  only_if('FIPS is not required for this image') { input('fips_required') }

  describe command('update-crypto-policies --show') do
    its('exit_status') { should eq 0 }
    its('stdout.strip') { should cmp 'FIPS' }
  end
end

control 'safbox-fips-3' do
  impact 1.0
  title 'The OpenSSL FIPS provider is loaded and active'
  desc 'In FIPS mode OpenSSL 3 must load its FIPS provider; without it, libraries fall back to unvalidated implementations.'
  only_if('FIPS is not required for this image') { input('fips_required') }

  describe command('openssl list -providers') do
    its('exit_status') { should eq 0 }
    its('stdout') { should match(/^\s+fips\n\s+name: .*FIPS Provider\n(\s+\w+: .*\n)*?\s+status: active$/) }
  end
end

control 'safbox-firewall-1' do
  impact 1.0
  title 'The firewall allows SSH and the proxy ports only'
  desc "ADR-0001 Quality Standards: the firewall allows SSH and the proxy ports only. Every interface is in the #{zone} zone, which is the default zone and allows exactly the firewall_services input and the HTTPS ports of the landing page and each application the image ships, with no other port, protocol, source port, forward port or rich rule, at runtime and permanently. On a hardened image the zone's target is DROP. The DNS and NTP services the Lockdown role allows by default are left out: they admit inbound queries to servers SAFBox does not run, while the box's own DNS and NTP client traffic returns as related to its outbound connections. Other zones hold no interface, and the only sources they hold are podman's container network subnets."

  describe command('firewall-cmd --get-default-zone') do
    its('stdout.strip') { should eq zone }
  end

  { 'runtime' => 'firewall-cmd', 'permanent' => 'firewall-cmd --permanent' }.each do |label, cmd|
    {
      'services' => want_services,
      'ports' => want_ports,
      'protocols' => [],
      'source-ports' => [],
      'forward-ports' => [],
    }.each do |what, want|
      describe "#{what.capitalize} the #{zone} zone allows (#{label})" do
        subject { command("#{cmd} --zone=#{zone} --list-#{what}").stdout.split.sort }
        it { should eq want }
      end
    end

    describe "Rich rules in the #{zone} zone (#{label})" do
      subject { command("#{cmd} --zone=#{zone} --list-rich-rules").stdout.strip }
      it { should be_empty }
    end
  end

  if hardened
    describe "Target of the #{zone} zone" do
      subject { command("firewall-cmd --permanent --zone=#{zone} --get-target").stdout.strip }
      it { should eq 'DROP' }
    end
  end

  # Subnets of every podman network, the only sources another zone may hold.
  podman_subnets = command("sh -c 'podman network ls --format \"{{.Name}}\" | xargs -r podman network inspect --format \"{{range .Subnets}}{{.Subnet}} {{end}}\"'").stdout.split
  other_zones = command('firewall-cmd --get-zones').stdout.split - [zone]
  describe 'Zones other than the default zone' do
    subject { other_zones }
    it { should_not be_empty }
  end
  other_zones.each do |other|
    describe "Interfaces in the #{other} zone" do
      subject { command("firewall-cmd --zone=#{other} --list-interfaces").stdout.split }
      it { should be_empty }
    end
    describe "Sources in the #{other} zone that are not podman network subnets" do
      subject { command("firewall-cmd --zone=#{other} --list-sources").stdout.split - podman_subnets }
      it { should be_empty }
    end
  end
end

